head.b:skin:
/* ============================================================
   Blogger integration layer for the EquityPilotAI API simulation.
   The application owns the viewport; Blogger chrome is neutralised.
   Every application rule below is namespaced under .epa
   ============================================================ */
html, body { margin: 0; padding: 0; background: #ffffff; min-height: 100%; }
body { -webkit-text-size-adjust: 100%; }
.section, .widget, .widget-content { margin: 0; padding: 0; }

/* The application root is rendered directly in the document body, so no
   Blogger widget has to succeed for the page to appear. */
#epa-root {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  min-height: 100vh;
}
.epa { display: block; width: 100%; box-sizing: border-box; }
.epa #epa-app, #epa-app { display: block; min-height: 60vh; }

/* The Blogger section exists so Layout keeps working. It renders nothing. */
.epa-host, .epa-host .widget, .epa-host-slot { display: none !important; }
.navbar, #navbar, #navbar-iframe { display: none !important; height: 0; visibility: hidden; }

.epa-noscript {
  margin: 24px auto; max-width: 640px; padding: 16px 18px;
  border: 1px solid #e2e8f0; border-radius: 8px;
  font: 14px/1.5 ui-sans-serif, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  color: #0f172a; background: #f7f9fc;
}

/* ==========================================================================
   1. DESIGN TOKENS  (ported from globals.css — navy / white / grey terminal)
   All selectors are scoped under .epa so Blogger's theme cannot leak in.
   ========================================================================== */
.epa{
  --navy-950:#060f1f; --navy-900:#0b1f3a; --navy-800:#12305c;
  --accent-500:#1f6feb; --accent-400:#4b8ef5; --accent-600:#1858c4;
  --gain:#0b7a3b; --loss:#b3261e; --warn:#b45309;
  --bg:#ffffff; --bg-elevated:#ffffff; --bg-subtle:#f7f9fc;
  --border:#e2e8f0; --border-strong:#cbd5e1;
  --text:#0f172a; --text-muted:#64748b; --header:#0b1f3a;
  --mono: ui-monospace,"SF Mono","JetBrains Mono",Menlo,Consolas,monospace;
  --sans: ui-sans-serif,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;

  background:var(--bg); color:var(--text); font-family:var(--sans);
  font-size:14px; line-height:1.45; -webkit-font-smoothing:antialiased;
  font-feature-settings:"tnum" 1;
  display:block; width:100%; box-sizing:border-box;
}
.epa.epa-dark{
  --bg:#060f1f; --bg-elevated:#0d1b30; --bg-subtle:#0b1728;
  --border:#1e304c; --border-strong:#2b4468;
  --text:#e8eef7; --text-muted:#8fa3bf; --header:#060f1f;
}
.epa *,.epa *::before,.epa *::after{box-sizing:border-box;}
.epa h1,.epa h2,.epa h3,.epa p,.epa ul,.epa ol,.epa figure{margin:0;padding:0;}
.epa ul{list-style:none;}
.epa a{color:inherit;text-decoration:none;}
.epa button,.epa input,.epa select,.epa textarea{font:inherit;color:inherit;}
.epa img{max-width:100%;}
.epa :focus-visible{outline:2px solid var(--accent-500);outline-offset:2px;}

/* Numerics are always tabular — a column of figures must align. */
.epa .num{font-family:var(--mono);font-variant-numeric:tabular-nums;
  font-size:.8125rem;letter-spacing:-.01em;}
.epa .gain{color:var(--gain);} .epa .loss{color:var(--loss);}
.epa .muted{color:var(--text-muted);}
.epa .mono{font-family:var(--mono);}
.epa .tiny{font-size:.6875rem;} .epa .xs{font-size:.75rem;} .epa .sm{font-size:.8125rem;}
.epa .b{font-weight:600;} .epa .right{text-align:right;} .epa .center{text-align:center;}
.epa .nowrap{white-space:nowrap;}

/* ==========================================================================
   2. SHELL — sidebar rail + topbar + mobile drawer
   ========================================================================== */
.epa-shell{display:flex;min-height:640px;width:100%;}
.epa-side{
  width:216px;flex:0 0 216px;background:var(--navy-900);
  display:flex;flex-direction:column;position:sticky;top:0;
  max-height:100vh;border-right:1px solid rgba(255,255,255,.07);
}
.epa.epa-dark .epa-side{background:#081426;}
.epa-brand{display:flex;align-items:center;gap:10px;padding:14px 16px;
  border-bottom:1px solid rgba(255,255,255,.1);}
.epa-logo{width:32px;height:32px;border-radius:6px;background:var(--accent-500);
  color:#fff;display:grid;place-items:center;font-weight:700;font-size:13px;flex:0 0 32px;}
.epa-brand-t{font-size:.8125rem;font-weight:600;color:#fff;line-height:1.15;}
.epa-brand-s{font-size:.625rem;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.45);}
.epa-nav{flex:1;overflow-y:auto;padding:8px;}
.epa-navgroup{font-size:.5625rem;letter-spacing:.1em;text-transform:uppercase;
  color:rgba(255,255,255,.35);padding:10px 10px 4px;}
.epa-navlink{display:flex;align-items:center;gap:9px;border-radius:5px;
  padding:7px 10px;font-size:.8125rem;color:rgba(255,255,255,.65);cursor:pointer;
  transition:background .12s,color .12s;min-height:34px;}
.epa-navlink:hover{background:rgba(255,255,255,.1);color:#fff;}
.epa-navlink.is-active{background:var(--accent-500);color:#fff;}
.epa-navlink .ico{width:15px;text-align:center;flex:0 0 15px;opacity:.9;}
.epa-navlink.is-disabled{opacity:.35;cursor:not-allowed;}
.epa-usercard{border-top:1px solid rgba(255,255,255,.1);padding:11px;}
.epa-avatar{width:28px;height:28px;border-radius:999px;background:rgba(255,255,255,.15);
  color:#fff;display:grid;place-items:center;font-size:.6875rem;font-weight:600;flex:0 0 28px;}
.epa-devnote{margin-top:8px;border:1px solid rgba(180,83,9,.45);background:rgba(180,83,9,.12);
  color:#f0b46b;border-radius:4px;padding:4px 6px;font-size:.5625rem;line-height:1.3;}

.epa-main{flex:1;min-width:0;display:flex;flex-direction:column;}
.epa-topbar{
  position:sticky;top:0;z-index:40;display:flex;align-items:center;gap:10px;
  padding:9px 14px;border-bottom:1px solid var(--border);
  background:linear-gradient(to bottom,var(--bg-elevated),var(--bg));
}
.epa-burger{display:none;}
.epa-searchwrap{position:relative;flex:1;max-width:520px;min-width:0;}
.epa-search{
  width:100%;font-family:var(--mono);font-size:.8125rem;background:var(--bg-subtle);
  border:1px solid var(--border);border-radius:6px;padding:7px 62px 7px 30px;color:var(--text);
  transition:border-color .1s,box-shadow .1s;
}
.epa-search:focus{border-color:var(--accent-500);box-shadow:0 0 0 3px rgba(31,111,235,.1);outline:none;}
.epa-searchicon{position:absolute;left:9px;top:50%;transform:translateY(-50%);
  color:var(--text-muted);font-size:12px;pointer-events:none;}
.epa-kbd{font-family:var(--mono);font-size:.625rem;padding:1px 5px;border-radius:3px;
  background:var(--bg-subtle);border:1px solid var(--border);color:var(--text-muted);}
.epa-searchwrap .epa-kbd{position:absolute;right:8px;top:50%;transform:translateY(-50%);}
.epa-results{
  position:absolute;left:0;right:0;top:calc(100% + 6px);z-index:60;
  background:var(--bg-elevated);border:1px solid var(--border);border-radius:8px;
  box-shadow:0 12px 32px -8px rgba(0,0,0,.25);overflow:hidden;max-height:340px;overflow-y:auto;
}
.epa-result{display:flex;justify-content:space-between;gap:10px;padding:8px 11px;cursor:pointer;
  border-bottom:1px solid var(--border);}
.epa-result:last-child{border-bottom:0;}
.epa-result:hover,.epa-result[aria-selected="true"]{background:var(--bg-subtle);}
.epa-content{padding:18px 16px 44px;max-width:1500px;width:100%;}

.epa-iconbtn{border:1px solid var(--border);background:var(--bg-elevated);border-radius:6px;
  padding:6px 9px;cursor:pointer;font-size:12px;color:var(--text-muted);min-height:32px;}
.epa-iconbtn:hover{color:var(--text);border-color:var(--border-strong);}

/* ==========================================================================
   3. PRIMITIVES — Card / Stat / Badge / Button / Empty / Skeleton
   ========================================================================== */
.epa-card{background:var(--bg-elevated);border:1px solid var(--border);border-radius:8px;
  box-shadow:0 1px 3px rgba(0,0,0,.05);overflow:hidden;min-width:0;}
.epa.epa-dark .epa-card{box-shadow:0 1px 3px rgba(0,0,0,.25);}
.epa-cardhead{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;
  padding:11px 15px;border-bottom:1px solid var(--border);background:var(--bg-elevated);}
.epa-cardtitle{font-size:.8125rem;font-weight:600;}
.epa-cardsub{font-size:.6875rem;color:var(--text-muted);margin-top:2px;}
.epa-cardbody{padding:15px;}
.epa-statlabel{font-size:.6875rem;font-weight:500;text-transform:uppercase;
  letter-spacing:.06em;color:var(--text-muted);}
.epa-statvalue{margin-top:4px;font-size:1.25rem;font-weight:600;font-family:var(--mono);
  font-variant-numeric:tabular-nums;letter-spacing:-.02em;}
.epa-stathint{margin-top:2px;font-size:.75rem;color:var(--text-muted);}
.epa-badge{display:inline-flex;align-items:center;gap:4px;border:1px solid var(--border);
  background:var(--bg-subtle);color:var(--text-muted);border-radius:4px;padding:2px 6px;
  font-size:.6875rem;font-weight:500;white-space:nowrap;}
.epa-badge.accent{background:rgba(31,111,235,.1);color:var(--accent-500);border-color:rgba(31,111,235,.25);}
.epa-badge.gain{background:rgba(11,122,59,.1);color:var(--gain);border-color:rgba(11,122,59,.25);}
.epa-badge.loss{background:rgba(179,38,30,.1);color:var(--loss);border-color:rgba(179,38,30,.25);}
.epa-badge.warn{background:rgba(180,83,9,.1);color:var(--warn);border-color:rgba(180,83,9,.25);}
.epa-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;
  border:1px solid var(--border);background:var(--bg-elevated);border-radius:6px;
  padding:7px 12px;font-size:.75rem;font-weight:500;cursor:pointer;min-height:34px;
  transition:background .1s,border-color .1s;}
.epa-btn:hover{border-color:var(--border-strong);background:var(--bg-subtle);}
.epa-btn.primary{background:var(--accent-500);border-color:var(--accent-500);color:#fff;}
.epa-btn.primary:hover{background:var(--accent-600);border-color:var(--accent-600);}
.epa-btn.danger{color:var(--loss);border-color:rgba(179,38,30,.35);}
.epa-btn:disabled{opacity:.4;cursor:not-allowed;}
.epa-btn.small{padding:4px 9px;min-height:28px;font-size:.6875rem;}
.epa-input,.epa-select{width:100%;background:var(--bg-elevated);border:1px solid var(--border);
  border-radius:6px;padding:7px 10px;font-size:.8125rem;min-height:34px;}
.epa-input:focus,.epa-select:focus{outline:none;border-color:var(--accent-500);
  box-shadow:0 0 0 3px rgba(31,111,235,.1);}
.epa-label{display:block;font-size:.6875rem;color:var(--text-muted);margin-bottom:4px;}
.epa-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;
  padding:52px 22px;text-align:center;}
.epa-empty .t{font-size:.875rem;font-weight:500;}
.epa-empty .d{margin-top:5px;font-size:.75rem;color:var(--text-muted);max-width:380px;}
.epa-skel{border-radius:6px;background:var(--bg-subtle);
  background-image:linear-gradient(90deg,var(--bg-subtle) 25%,var(--bg-elevated) 50%,var(--bg-subtle) 75%);
  background-size:200% 100%;animation:epa-shimmer 1.4s infinite linear;}
@keyframes epa-shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}
@keyframes epa-fadeup{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.epa-fade{animation:epa-fadeup .26s ease-out both;}

/* Layout helpers */
.epa-grid{display:grid;gap:14px;}
.epa-g2{grid-template-columns:repeat(2,minmax(0,1fr));}
.epa-g3{grid-template-columns:repeat(3,minmax(0,1fr));}
.epa-g4{grid-template-columns:repeat(4,minmax(0,1fr));}
.epa-split{display:grid;gap:16px;grid-template-columns:2fr 1fr;}
.epa-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;}
.epa-between{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:12px;}
.epa-stack{display:flex;flex-direction:column;gap:16px;}
.epa-h1{font-size:1.25rem;font-weight:600;letter-spacing:-.01em;}
.epa-sub{margin-top:3px;font-size:.8125rem;color:var(--text-muted);}
.epa-sectiontitle{font-size:.75rem;font-weight:600;text-transform:uppercase;
  letter-spacing:.08em;color:var(--text-muted);}
.epa-divider{height:1px;background:var(--border);margin:12px 0;}

/* ==========================================================================
   4. DATA GRID — the institutional table (ported .grid-table / .scroll-x)
   ========================================================================== */
.epa-scroll{overflow-x:auto;overflow-y:hidden;min-width:0;max-width:100%;
  -webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;}
.epa-table{width:100%;border-collapse:separate;border-spacing:0;}
.epa-table thead th{
  position:sticky;top:0;z-index:10;background:var(--bg-subtle);
  border-bottom:1px solid var(--border-strong);
  font-size:.6875rem;font-weight:600;text-transform:uppercase;letter-spacing:.04em;
  color:var(--text-muted);padding:8px 12px;text-align:right;white-space:nowrap;}
.epa-table thead th:first-child{text-align:left;position:sticky;left:0;z-index:15;background:var(--bg-subtle);}
.epa-table tbody td{padding:6px 12px;border-bottom:1px solid var(--border);
  text-align:right;white-space:nowrap;height:32px;font-size:.8125rem;}
.epa-table tbody td:first-child{text-align:left;position:sticky;left:0;z-index:5;background:var(--bg-elevated);}
.epa-table tbody tr:hover td{background:var(--bg-subtle);}
.epa-table tbody tr.is-subtotal td{font-weight:600;background:rgba(31,111,235,.05);}
.epa-table tbody tr.is-total td{font-weight:700;background:rgba(31,111,235,.08);
  border-top:1px solid var(--border-strong);}
.epa-table td.l,.epa-table th.l{text-align:left;}
.epa-link{color:var(--accent-500);cursor:pointer;}
.epa-link:hover{text-decoration:underline;}

/* Tab strips — single scrolling row, never wrap */
.epa-tabs{display:flex;flex-wrap:nowrap;overflow-x:auto;overflow-y:hidden;min-width:0;
  max-width:100%;gap:2px;border-bottom:1px solid var(--border);margin-bottom:16px;
  scrollbar-width:none;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;}
.epa-tabs::-webkit-scrollbar{display:none;}
.epa-tab{flex:0 0 auto;white-space:nowrap;margin-bottom:-1px;border:0;background:none;
  border-bottom:2px solid transparent;padding:8px 12px;font-size:.8125rem;
  color:var(--text-muted);cursor:pointer;min-height:36px;}
.epa-tab:hover{color:var(--text);}
.epa-tab.is-active{border-bottom-color:var(--accent-500);color:var(--accent-500);font-weight:500;}

/* Score bars, verdicts, timeline, chat — ported premium components */
.epa-bar{height:5px;background:var(--bg-subtle);border-radius:999px;overflow:hidden;}
.epa-bar>span{display:block;height:100%;border-radius:999px;
  background:linear-gradient(to right,#1f6feb,#4b8ef5);transition:width .4s cubic-bezier(.4,0,.2,1);}
.epa-bar.gain>span{background:linear-gradient(to right,#0b7a3b,#15803d);}
.epa-bar.loss>span{background:linear-gradient(to right,#b3261e,#dc2626);}
.epa-verdict{border-left:4px solid var(--accent-500);padding:11px 14px;background:var(--bg-subtle);
  border-radius:0 6px 6px 0;}
.epa-verdict.bull{border-left-color:var(--gain);} .epa-verdict.bear{border-left-color:var(--loss);}
.epa-timeline{position:relative;padding-left:26px;padding-bottom:14px;}
.epa-timeline::before{content:"";position:absolute;left:6px;top:6px;bottom:0;width:2px;background:var(--border);}
.epa-timeline:last-child::before{display:none;}
.epa-dot{position:absolute;left:0;top:4px;width:12px;height:12px;border-radius:999px;
  background:var(--bg-elevated);border:2px solid var(--accent-500);}
.epa-bubble{max-width:82%;padding:9px 13px;border-radius:8px;font-size:.8125rem;line-height:1.4;}
.epa-bubble.user{background:var(--accent-500);color:#fff;margin-left:auto;border-bottom-right-radius:2px;}
.epa-bubble.bot{background:var(--bg-subtle);border:1px solid var(--border);border-bottom-left-radius:2px;}
.epa-chatlog{display:flex;flex-direction:column;gap:9px;max-height:320px;overflow-y:auto;padding:4px;}
.epa-chip{border:1px solid var(--border);background:var(--bg-subtle);border-radius:999px;
  padding:4px 10px;font-size:.6875rem;cursor:pointer;white-space:nowrap;}
.epa-chip.is-active{background:rgba(31,111,235,.12);border-color:rgba(31,111,235,.35);color:var(--accent-500);}
.epa-kv{display:flex;justify-content:space-between;gap:12px;padding:5px 0;
  border-bottom:1px dashed var(--border);font-size:.8125rem;}
.epa-kv:last-child{border-bottom:0;}
.epa-note{border:1px solid var(--border);background:var(--bg-subtle);border-radius:6px;
  padding:9px 11px;font-size:.75rem;color:var(--text-muted);}
.epa-alert{border-radius:6px;padding:9px 11px;font-size:.75rem;display:flex;gap:8px;}
.epa-alert.err{border:1px solid rgba(179,38,30,.4);background:rgba(179,38,30,.08);color:var(--loss);}
.epa-alert.ok{border:1px solid rgba(11,122,59,.4);background:rgba(11,122,59,.08);color:var(--gain);}
.epa-alert.warn{border:1px solid rgba(180,83,9,.4);background:rgba(180,83,9,.08);color:var(--warn);}

/* Auth screen */
.epa-auth{display:flex;align-items:center;justify-content:center;padding:48px 16px;min-height:560px;}
.epa-authbox{width:100%;max-width:380px;}
.epa-authcard{border:1px solid var(--border);background:var(--bg-elevated);border-radius:10px;
  padding:20px;box-shadow:0 8px 30px -12px rgba(0,0,0,.2);}

/* Modal */
.epa-modalwrap{position:fixed;inset:0;z-index:9000;background:rgba(4,10,20,.55);
  display:flex;align-items:center;justify-content:center;padding:16px;}
.epa-modal{width:100%;max-width:420px;background:var(--bg-elevated);border:1px solid var(--border);
  border-radius:10px;box-shadow:0 24px 60px -20px rgba(0,0,0,.5);overflow:hidden;}

/* Charts (inline SVG, no library) */
.epa-chart{width:100%;height:auto;display:block;}
.epa-legend{display:flex;flex-wrap:wrap;gap:12px;font-size:.6875rem;color:var(--text-muted);}
.epa-swatch{width:9px;height:9px;border-radius:2px;display:inline-block;margin-right:5px;}
.epa-heat{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:6px;}
.epa-heatcell{border-radius:5px;padding:8px;color:#fff;font-size:.6875rem;
  transition:transform .08s,filter .08s;cursor:pointer;}
.epa-heatcell:hover{transform:scale(1.03);filter:brightness(1.08);}

/* Scrollbars */
.epa ::-webkit-scrollbar{width:10px;height:10px;}
.epa ::-webkit-scrollbar-track{background:var(--bg-subtle);}
.epa ::-webkit-scrollbar-thumb{background:var(--border-strong);border-radius:5px;border:2px solid var(--bg-subtle);}

/* ==========================================================================
   5. RESPONSIVE — mobile drawer + density (mirrors the app's 1024/400 bands)
   ========================================================================== */
@media (max-width:1023px){
  .epa-side{position:fixed;left:0;top:0;bottom:0;z-index:9500;transform:translateX(-105%);
    transition:transform .22s ease;max-height:100vh;box-shadow:0 0 40px rgba(0,0,0,.4);}
  .epa-side.is-open{transform:none;}
  .epa-backdrop{position:fixed;inset:0;background:rgba(4,10,20,.5);z-index:9400;}
  .epa-burger{display:inline-flex;}
  .epa-g4{grid-template-columns:repeat(2,minmax(0,1fr));}
  .epa-g3{grid-template-columns:repeat(2,minmax(0,1fr));}
  .epa-split{grid-template-columns:minmax(0,1fr);}
  .epa-table thead th{padding:7px 8px;font-size:.625rem;}
  .epa-table tbody td{padding:6px 8px;height:30px;font-size:.75rem;}
  .epa .num{font-size:.75rem;}
  .epa-table tbody td:first-child,.epa-table thead th:first-child{
    box-shadow:1px 0 0 0 var(--border);max-width:11.5rem;overflow:hidden;text-overflow:ellipsis;}
  .epa-content{padding:14px 12px 40px;}
  .epa ::-webkit-scrollbar{width:6px;height:6px;}
}
@media (max-width:640px){
  .epa-g4,.epa-g3,.epa-g2{grid-template-columns:minmax(0,1fr);}
  .epa-h1{font-size:1.0625rem;}
}
@media (max-width:400px){
  .epa-table thead th{padding:6px 7px;} .epa-table tbody td{padding:5px 7px;}
  .epa-table tbody td:first-child{max-width:9rem;} .epa .num{font-size:.6875rem;}
}
@media print{ .epa-side,.epa-topbar{display:none;} }

/* API debug panel */
.epa-debug{position:fixed;right:14px;bottom:14px;z-index:99998;width:min(680px,calc(100vw - 28px));
  max-height:52vh;display:flex;flex-direction:column;background:var(--bg-elevated);
  border:1px solid var(--border-strong);border-radius:10px;box-shadow:0 22px 50px -18px rgba(0,0,0,.45);overflow:hidden;}
.epa-debughead{display:flex;align-items:center;gap:9px;padding:8px 12px;border-bottom:1px solid var(--border);
  background:var(--bg-subtle);font-size:.8125rem;}
.epa-debugbody{overflow:auto;padding:8px 10px;}
.epa-debugrow{display:flex;align-items:center;gap:9px;padding:5px 4px;border-bottom:1px solid var(--border);}
.epa-debugrow:last-child{border-bottom:0;}
/* JSON viewer */
.epa-json{margin:0;padding:12px;background:var(--bg-subtle);border:1px solid var(--border);border-radius:6px;
  font-family:var(--mono);font-size:.75rem;line-height:1.45;white-space:pre;overflow:auto;max-height:60vh;}
/* Sortable headers */
.epa-table thead th.epa-sortable{cursor:pointer;user-select:none;}
.epa-table thead th.epa-sortable:hover{color:var(--text);}
.epa-table thead th.is-sorted{color:var(--accent-500);}
@media (max-width:640px){ .epa-debug{right:8px;left:8px;width:auto;max-height:60vh;} }

