(function () {
  "use strict";

  /* ==========================================================================
     1. CONFIG
     ========================================================================== */
  var CONFIG = {
    USE_MOCK: true,
    API_BASE: "",
    DATA_VERSION: "2026.08.20-mock-500",
    APP_VERSION: "1.0.0-blogger-prototype",
    LATENCY_MIN_MS: 6,
    LATENCY_MAX_MS: 55,
    PAGE_SIZE: 25,
    COMPANY_COUNT: 500,
    FISCAL_YEARS: 6,
    STORAGE_PREFIX: "epa:",
    DEBUG_LOG_LIMIT: 60,
    RENDER_CHUNK: 40
  };

  /* ==========================================================================
     2. FORMATTING AND DATA QUALITY
     Indian numbering, rupee crore, percentages, negatives in parentheses,
     and one single place that decides what a missing value looks like.
     ========================================================================== */
  var EM = "\u2014";
  var RS = "\u20B9";

  function has(v) {
    return v !== null && v !== undefined && v !== "" && !(typeof v === "number" && isNaN(v));
  }
  function indianGroup(value, decimals) {
    var neg = value < 0;
    var fixed = Math.abs(value).toFixed(decimals);
    var parts = fixed.split(".");
    var intPart = parts[0], dec = parts[1], out;
    if (intPart.length <= 3) { out = intPart; }
    else {
      out = intPart.slice(0, -3).replace(/\B(?=(\d{2})+(?!\d))/g, ",") + "," + intPart.slice(-3);
    }
    var joined = dec ? out + "." + dec : out;
    return neg ? "(" + joined + ")" : joined;
  }
  function plain(v, d) { return has(v) ? indianGroup(v, d === undefined ? 0 : d) : EM; }
  function crore(v, d) { return has(v) ? indianGroup(v, d === undefined ? 1 : d) : EM; }
  function croreRs(v, d) { return has(v) ? RS + indianGroup(v, d === undefined ? 1 : d) + " cr" : EM; }
  function rupees(v, d) { return has(v) ? RS + indianGroup(v, d === undefined ? 2 : d) : EM; }
  function marketCapFmt(v) {
    if (!has(v)) return EM;
    if (Math.abs(v) >= 100000) return RS + (v / 100000).toFixed(2) + " L Cr";
    return RS + indianGroup(v, 0) + " Cr";
  }
  function pct(v, d) {
    if (!has(v)) return EM;
    var x = v * 100, s = Math.abs(x).toFixed(d === undefined ? 1 : d) + "%";
    return x < 0 ? "(" + s + ")" : s;
  }
  function pctPoints(v, d) {
    if (!has(v)) return EM;
    var s = Math.abs(v).toFixed(d === undefined ? 1 : d) + "%";
    return v < 0 ? "(" + s + ")" : s;
  }
  function signedPct(v, d) {
    if (!has(v)) return EM;
    var x = v * 100;
    return (x >= 0 ? "+" : "\u2212") + Math.abs(x).toFixed(d === undefined ? 2 : d) + "%";
  }
  function mult(v, d) { return has(v) ? v.toFixed(d === undefined ? 2 : d) + "x" : EM; }
  function fyLabel(y) { return "FY" + String(y).slice(-2); }
  function signCls(v) { return !has(v) ? "muted" : v > 0 ? "gain" : v < 0 ? "loss" : "muted"; }
  function dateShort(iso) {
    var d = new Date(iso);
    return isNaN(d.getTime()) ? EM : d.toLocaleDateString(undefined, { day: "2-digit", month: "short", year: "numeric" });
  }
  function dateTime(iso) {
    var d = new Date(iso);
    return isNaN(d.getTime()) ? EM : d.toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
  }
  function esc(s) {
    return String(s === null || s === undefined ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function nowMs() {
    return (window.performance && window.performance.now) ? window.performance.now() : Date.now();
  }

  /* ==========================================================================
     3. MOCK DATABASE
     500 Indian listed companies. Reference names are real; every number is
     simulated. Nothing here is live market data and each record says so.
     ========================================================================== */
  function seeded(seed) {
    var s = seed % 2147483647;
    if (s <= 0) s += 2147483646;
    return function () { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; };
  }
  function hashCode(str) {
    var h = 0;
    for (var i = 0; i < str.length; i++) { h = ((h << 5) - h + str.charCodeAt(i)) | 0; }
    return Math.abs(h) + 7;
  }

